A single file with no dependencies. Columns and cards are saved to `localStorage` and survive reloads.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Kanban</title>
<style>
  body { font-family: system-ui, sans-serif; background: #f4f5f7; margin: 0; padding: 1.5rem; }
  .board { display: grid; grid-template-columns: repeat(3, minmax(220px, 1fr)); gap: 1rem; }
  .col { background: #ebecf0; border-radius: 8px; padding: .75rem; min-height: 300px; }
  .col.over { outline: 2px dashed #4c9aff; }
  .col h2 { font-size: 1rem; margin: 0 0 .5rem; }
  .card { background: #fff; padding: .6rem .8rem; border-radius: 6px; margin-bottom: .5rem;
          box-shadow: 0 1px 2px rgb(0 0 0 / .15); cursor: grab; }
  .card.dragging { opacity: .4; }
  .add { width: 100%; padding: .4rem; margin-top: .3rem; }
</style>
</head>
<body>
<div class="board" id="board"></div>

<script>
const KEY = "kanban-v1";
const state = JSON.parse(localStorage.getItem(KEY)) ?? {
  todo: ["Design logo"], doing: ["Write docs"], done: ["Set up repo"]
};
const titles = { todo: "To do", doing: "In progress", done: "Done" };
let dragged = null;   // { card, from }

function save() { localStorage.setItem(KEY, JSON.stringify(state)); }

function render() {
  const board = document.getElementById("board");
  board.replaceChildren(...Object.keys(state).map(col => {
    const el = document.createElement("section");
    el.className = "col";
    el.dataset.col = col;
    const h = document.createElement("h2");
    h.textContent = `${titles[col]} (${state[col].length})`;
    el.append(h, ...state[col].map((text, i) => cardEl(col, text, i)));
    const add = document.createElement("button");
    add.className = "add";
    add.textContent = "+ Add card";
    add.onclick = () => {
      const text = prompt("Card text");
      if (text?.trim()) { state[col].push(text.trim()); save(); render(); }
    };
    el.append(add);
    el.addEventListener("dragover", e => { e.preventDefault(); el.classList.add("over"); });
    el.addEventListener("dragleave", () => el.classList.remove("over"));
    el.addEventListener("drop", e => {
      e.preventDefault();
      el.classList.remove("over");
      if (!dragged) return;
      state[dragged.from].splice(dragged.index, 1);
      state[col].push(dragged.text);
      dragged = null;
      save(); render();
    });
    return el;
  }));
}

function cardEl(col, text, index) {
  const c = document.createElement("div");
  c.className = "card";
  c.draggable = true;
  c.textContent = text;
  c.addEventListener("dragstart", () => {
    dragged = { from: col, index, text };
    c.classList.add("dragging");
  });
  c.addEventListener("dragend", () => c.classList.remove("dragging"));
  return c;
}

render();
</script>
</body>
</html>
```

The native HTML5 drag-and-drop API needs no library. `textContent` is used instead of `innerHTML`, so card text can't inject markup.

Writes Markdown on the left and renders it on the right. The renderer escapes HTML first, so pasted `<script>` tags are shown as text.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Markdown Editor</title>
<style>
  body { margin: 0; font-family: system-ui; height: 100vh; display: flex; flex-direction: column; }
  .panes { flex: 1; display: grid; grid-template-columns: 1fr 1fr; min-height: 0; }
  textarea { border: 0; padding: 1rem; font: 14px/1.5 ui-monospace, monospace; resize: none; border-right: 1px solid #ddd; }
  #preview { padding: 1rem; overflow: auto; }
  pre { background: #f6f8fa; padding: .75rem; overflow-x: auto; }
  code { background: #f6f8fa; padding: 0 .2rem; }
</style>
</head>
<body>
<div class="panes">
  <textarea id="src" spellcheck="false">
# Hello

Some **bold** text, a [link](https://example.com), and `inline code`.

- item one
- item two

```js
console.log("hi");
```
  </textarea>
  <div id="preview"></div>
</div>

<script>
const escape = s => s.replace(/[&<>"']/g, c =>
  ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

// Inline rules run after escaping, so user input can never create tags except ours.
function inline(s) {
  return s
    .replace(/`([^`]+)`/g, "<code>$1</code>")
    .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
    .replace(/\*(.+?)\*/g, "<em>$1</em>")
    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,
             '<a href="$2" rel="noopener noreferrer">$1</a>');
}

function render(md) {
  const out = [];
  let inCode = false, inList = false;
  for (const raw of md.split("\n")) {
    if (raw.startsWith("```")) {
      out.push(inCode ? "</code></pre>" : "<pre><code>");
      inCode = !inCode;
      continue;
    }
    if (inCode) { out.push(escape(raw) + "\n"); continue; }
    const line = escape(raw);
    const h = line.match(/^(#{1,6})\s+(.*)/);
    const li = line.match(/^[-*]\s+(.*)/);
    if (li && !inList) { out.push("<ul>"); inList = true; }
    if (!li && inList) { out.push("</ul>"); inList = false; }
    if (h) out.push(`<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`);
    else if (li) out.push(`<li>${inline(li[1])}</li>`);
    else if (line.trim()) out.push(`<p>${inline(line)}</p>`);
  }
  if (inList) out.push("</ul>");
  return out.join("\n");
}

const src = document.getElementById("src");
const preview = document.getElementById("preview");
src.addEventListener("input", () => preview.innerHTML = render(src.value));
preview.innerHTML = render(src.value);
</script>
</body>
</html>
```

The security rule is that escaping comes first and Markdown rules are applied afterward. Reversing the order is a common XSS bug. For production, use a maintained parser such as `marked` together with `DOMPurify`.

Follows the WAI-ARIA Tabs pattern: arrow keys move between tabs, Home and End jump to the ends, and only the active tab is in the tab order.

```html
<div class="tabs">
  <div role="tablist" aria-label="Account settings">
    <button role="tab" id="t-profile" aria-controls="p-profile" aria-selected="true" tabindex="0">Profile</button>
    <button role="tab" id="t-billing" aria-controls="p-billing" aria-selected="false" tabindex="-1">Billing</button>
    <button role="tab" id="t-security" aria-controls="p-security" aria-selected="false" tabindex="-1">Security</button>
  </div>
  <section role="tabpanel" id="p-profile" aria-labelledby="t-profile">Profile content</section>
  <section role="tabpanel" id="p-billing" aria-labelledby="t-billing" hidden>Billing content</section>
  <section role="tabpanel" id="p-security" aria-labelledby="t-security" hidden>Security content</section>
</div>

<style>
  [role="tab"] { padding: .5rem 1rem; border: 0; background: none; cursor: pointer; border-bottom: 2px solid transparent; }
  [role="tab"][aria-selected="true"] { border-bottom-color: #2563eb; font-weight: 600; }
  [role="tab"]:focus-visible { outline: 2px solid #2563eb; outline-offset: 2px; }
  [role="tabpanel"] { padding: 1rem; }
</style>

<script>
const tablist = document.querySelector('[role="tablist"]');
const tabs = [...tablist.querySelectorAll('[role="tab"]')];

function select(tab, focus = true) {
  for (const t of tabs) {
    const on = t === tab;
    t.setAttribute("aria-selected", on);
    t.tabIndex = on ? 0 : -1;
    document.getElementById(t.getAttribute("aria-controls")).hidden = !on;
  }
  if (focus) tab.focus();
}

tablist.addEventListener("click", e => {
  const tab = e.target.closest('[role="tab"]');
  if (tab) select(tab, false);
});

tablist.addEventListener("keydown", e => {
  const i = tabs.indexOf(document.activeElement);
  if (i < 0) return;
  const map = {
    ArrowRight: (i + 1) % tabs.length,
    ArrowLeft: (i - 1 + tabs.length) % tabs.length,
    Home: 0,
    End: tabs.length - 1,
  };
  if (e.key in map) { e.preventDefault(); select(tabs[map[e.key]]); }
});
</script>
```

Only the active tab gets `tabindex="0"`, which keeps the tab order short. Screen readers announce the selected state through `aria-selected`.

Press Ctrl+K (or Cmd+K) to open a searchable list of actions. Matching is fuzzy: the query letters must appear in order, not next to each other.

```html
<style>
  #palette { position: fixed; inset: 0; background: rgb(0 0 0 / .4); display: none; align-items: flex-start; justify-content: center; padding-top: 15vh; }
  #palette.open { display: flex; }
  .box { background: #fff; width: min(560px, 90vw); border-radius: 10px; overflow: hidden; font-family: system-ui; }
  #q { width: 100%; box-sizing: border-box; padding: 1rem; font-size: 1rem; border: 0; border-bottom: 1px solid #ddd; outline: none; }
  #list { list-style: none; margin: 0; padding: 0; max-height: 50vh; overflow: auto; }
  #list li { padding: .6rem 1rem; cursor: pointer; }
  #list li.active { background: #2563eb; color: #fff; }
</style>

<div id="palette"><div class="box">
  <input id="q" placeholder="Type a command…" autocomplete="off">
  <ul id="list"></ul>
</div></div>

<script>
const commands = [
  { name: "New document",     run: () => alert("new doc") },
  { name: "Open settings",    run: () => alert("settings") },
  { name: "Toggle dark mode", run: () => document.body.classList.toggle("dark") },
  { name: "Export as PDF",    run: () => alert("export") },
  { name: "Sign out",         run: () => alert("bye") },
];

// Every query character must appear in order. Earlier and consecutive matches score higher.
function fuzzyScore(query, text) {
  let score = 0, ti = 0, last = -2;
  const t = text.toLowerCase();
  for (const ch of query.toLowerCase()) {
    const found = t.indexOf(ch, ti);
    if (found === -1) return -1;
    score += found === last + 1 ? 3 : 1;
    score -= found * 0.01;
    last = found; ti = found + 1;
  }
  return score;
}

const palette = document.getElementById("palette");
const input = document.getElementById("q");
const list = document.getElementById("list");
let shown = [], active = 0;

function refresh() {
  shown = commands
    .map(c => ({ c, s: fuzzyScore(input.value, c.name) }))
    .filter(x => x.s >= 0)
    .sort((a, b) => b.s - a.s)
    .map(x => x.c);
  active = 0;
  list.replaceChildren(...shown.map((c, i) => {
    const li = document.createElement("li");
    li.textContent = c.name;
    if (i === active) li.classList.add("active");
    li.onmousedown = e => { e.preventDefault(); run(c); };
    return li;
  }));
}

function run(cmd) { close(); cmd.run(); }
function open() { palette.classList.add("open"); input.value = ""; input.focus(); refresh(); }
function close() { palette.classList.remove("open"); }

document.addEventListener("keydown", e => {
  if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "k") {
    e.preventDefault();
    palette.classList.contains("open") ? close() : open();
  }
});
input.addEventListener("input", refresh);
input.addEventListener("keydown", e => {
  if (e.key === "Escape") close();
  if (e.key === "ArrowDown") { active = Math.min(active + 1, shown.length - 1); highlight(); e.preventDefault(); }
  if (e.key === "ArrowUp")   { active = Math.max(active - 1, 0); highlight(); e.preventDefault(); }
  if (e.key === "Enter" && shown[active]) run(shown[active]);
});
function highlight() {
  [...list.children].forEach((li, i) => li.classList.toggle("active", i === active));
}
palette.addEventListener("mousedown", e => { if (e.target === palette) close(); });
</script>
```

The scoring rewards consecutive matches, so "nd" ranks "New document" above "Export as PDF". The same pattern works for file pickers and search boxes.

Uses `<canvas>` to resize and re-encode a picked image as JPEG or WebP. No server work is needed to shrink the file.

```html
<input type="file" id="pick" accept="image/*">
<p id="info"></p>
<img id="preview" alt="" style="max-width:300px">

<script>
async function compress(file, { maxSide = 1600, quality = 0.8, type = "image/webp" } = {}) {
  const bitmap = await createImageBitmap(file);          // decodes off the main thread
  const scale = Math.min(1, maxSide / Math.max(bitmap.width, bitmap.height));
  const w = Math.round(bitmap.width * scale);
  const h = Math.round(bitmap.height * scale);

  const canvas = new OffscreenCanvas(w, h);
  const ctx = canvas.getContext("2d");
  ctx.drawImage(bitmap, 0, 0, w, h);
  bitmap.close();                                        // free decoded pixels

  const blob = await canvas.convertToBlob({ type, quality });
  return { blob, width: w, height: h };
}

document.getElementById("pick").addEventListener("change", async e => {
  const file = e.target.files[0];
  if (!file) return;
  const { blob, width, height } = await compress(file);
  document.getElementById("preview").src = URL.createObjectURL(blob);
  document.getElementById("info").textContent =
    `${(file.size / 1024).toFixed(0)} KB → ${(blob.size / 1024).toFixed(0)} KB (${width}×${height})`;
  // upload with fetch(url, { method: "POST", body: formData }) where formData.append("image", blob, "photo.webp")
});
</script>
```

`createImageBitmap` decodes without blocking the page. `OffscreenCanvas` can also run inside a Web Worker, so large batches don't freeze the UI. Some older Safari versions don't support WebP encoding, so check `blob.type` and fall back to `image/jpeg`.

Uses timestamps instead of counting `setInterval` ticks, so the timer stays correct when the tab is throttled in the background. The beep is generated with the Web Audio API, so no audio file is needed.

```html
<div style="font-family:system-ui;text-align:center;margin-top:3rem">
  <h1 id="clock" style="font-size:4rem;font-variant-numeric:tabular-nums">25:00</h1>
  <button id="toggle">Start</button>
  <button id="reset">Reset</button>
</div>

<script>
const WORK = 25 * 60 * 1000;
let remaining = WORK;      // ms left when paused
let endsAt = null;         // timestamp when running
let timerId = null;

const clock = document.getElementById("clock");
const toggle = document.getElementById("toggle");

function format(ms) {
  const s = Math.ceil(ms / 1000);
  return `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;
}

function beep() {
  const ctx = new AudioContext();
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.frequency.value = 880;
  gain.gain.setValueAtTime(0.3, ctx.currentTime);
  gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 1);
  osc.connect(gain).connect(ctx.destination);
  osc.start();
  osc.stop(ctx.currentTime + 1);
}

function tick() {
  const left = endsAt - Date.now();
  if (left <= 0) {
    clearInterval(timerId); timerId = null; endsAt = null; remaining = WORK;
    clock.textContent = "00:00";
    toggle.textContent = "Start";
    beep();
    return;
  }
  clock.textContent = format(left);
}

toggle.onclick = () => {
  if (timerId) {                      // pause
    remaining = endsAt - Date.now();
    clearInterval(timerId); timerId = null; endsAt = null;
    toggle.textContent = "Start";
  } else {                            // start / resume
    endsAt = Date.now() + remaining;
    timerId = setInterval(tick, 250);
    toggle.textContent = "Pause";
    tick();
  }
};

document.getElementById("reset").onclick = () => {
  clearInterval(timerId); timerId = null; endsAt = null;
  remaining = WORK;
  clock.textContent = format(WORK);
  toggle.textContent = "Start";
};
</script>
```

The browser may delay `setInterval` callbacks in background tabs, but `Date.now()` is still correct when the next tick runs. The `AudioContext` is created on a click so browsers allow sound. Create it lazily, and reuse one context in a larger app.

Only the rows visible in the viewport (plus a small buffer) exist in the DOM. Scrolling reuses a fixed spacer to keep the scrollbar accurate.

```html
<div id="viewport" style="height:400px;overflow:auto;border:1px solid #ccc;position:relative">
  <div id="spacer" style="position:relative"></div>
</div>

<script>
const ROW_H = 32;
const TOTAL = 100_000;
const BUFFER = 8;

const viewport = document.getElementById("viewport");
const spacer = document.getElementById("spacer");
spacer.style.height = `${TOTAL * ROW_H}px`;

const pool = [];                              // reused row elements
for (let i = 0; i < Math.ceil(viewport.clientHeight / ROW_H) + BUFFER * 2; i++) {
  const row = document.createElement("div");
  row.style.cssText = `position:absolute;left:0;right:0;height:${ROW_H}px;line-height:${ROW_H}px;padding:0 .5rem;box-sizing:border-box`;
  spacer.append(row);
  pool.push(row);
}

function render() {
  const first = Math.max(0, Math.floor(viewport.scrollTop / ROW_H) - BUFFER);
  pool.forEach((row, k) => {
    const index = first + k;
    if (index >= TOTAL) { row.style.display = "none"; return; }
    row.style.display = "";
    row.style.transform = `translateY(${index * ROW_H}px)`;
    row.textContent = `Row ${index + 1}`;
  });
}

viewport.addEventListener("scroll", () => requestAnimationFrame(render), { passive: true });
render();
</script>
```

The DOM holds about 25 elements regardless of the dataset size. Transforms are used for positioning, so the browser doesn't re-run layout for each row. Variable-height rows need a measurement cache, and the `ROW_H` constant must change to a per-index lookup.

```html
<canvas id="c" width="800" height="500" style="border:1px solid #888;touch-action:none"></canvas>
<div>
  <button id="undo">Undo</button>
  <button id="redo">Redo</button>
  <button id="save">Save PNG</button>
  <input type="color" id="color" value="#222">
</div>

<script>
const canvas = document.getElementById("c");
const ctx = canvas.getContext("2d");
ctx.lineCap = "round";
ctx.lineWidth = 4;

// Each stroke is stored as a list of points, so undo can replay the whole canvas.
const strokes = [];
const undone = [];
let current = null;

function redraw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (const s of strokes) {
    ctx.strokeStyle = s.color;
    ctx.beginPath();
    s.points.forEach((p, i) => i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y));
    ctx.stroke();
  }
}

const pos = e => {
  const r = canvas.getBoundingClientRect();
  return { x: (e.clientX - r.left) * canvas.width / r.width,
           y: (e.clientY - r.top) * canvas.height / r.height };
};

canvas.addEventListener("pointerdown", e => {
  canvas.setPointerCapture(e.pointerId);
  current = { color: document.getElementById("color").value, points: [pos(e)] };
  strokes.push(current);
  undone.length = 0;
});
canvas.addEventListener("pointermove", e => {
  if (!current) return;
  current.points.push(pos(e));
  redraw();
});
canvas.addEventListener("pointerup", () => current = null);

document.getElementById("undo").onclick = () => {
  if (strokes.length) { undone.push(strokes.pop()); redraw(); }
};
document.getElementById("redo").onclick = () => {
  if (undone.length) { strokes.push(undone.pop()); redraw(); }
};
document.getElementById("save").onclick = () => {
  const a = document.createElement("a");
  a.download = "drawing.png";
  a.href = canvas.toDataURL("image/png");
  a.click();
};
</script>
```

Pointer events handle mouse, touch, and pen with one code path. `setPointerCapture` keeps the stroke going if the cursor leaves the canvas. Storing vector points instead of pixels is what makes undo cheap.

Three files in the same folder, served over HTTPS or `localhost`.

`index.html`:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<link rel="manifest" href="manifest.json">
<meta name="theme-color" content="#2563eb">
<title>Notes PWA</title>
</head>
<body>
<h1>Offline notes</h1>
<p id="status"></p>
<script>
const status = document.getElementById("status");
const update = () => status.textContent = navigator.onLine ? "Online" : "Offline";
addEventListener("online", update); addEventListener("offline", update); update();
if ("serviceWorker" in navigator) navigator.serviceWorker.register("sw.js");
</script>
</body>
</html>
```

`manifest.json`:
```json
{ "name": "Notes", "short_name": "Notes", "start_url": "./index.html",
  "display": "standalone", "background_color": "#ffffff", "theme_color": "#2563eb" }
```

`sw.js`:
```javascript
const CACHE = "notes-v2";
const ASSETS = ["./", "./index.html", "./manifest.json"];

self.addEventListener("install", e =>
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(ASSETS)).then(() => self.skipWaiting())));

self.addEventListener("activate", e =>
  e.waitUntil(caches.keys().then(keys =>
    Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim())));

// Network first for HTML so users get updates; cache first for everything else.
self.addEventListener("fetch", e => {
  if (e.request.method !== "GET") return;
  const isPage = e.request.mode === "navigate";
  e.respondWith(isPage
    ? fetch(e.request).then(r => { caches.open(CACHE).then(c => c.put(e.request, r.clone())); return r; })
        .catch(() => caches.match(e.request))
    : caches.match(e.request).then(hit => hit || fetch(e.request)));
});
```

Bump the `CACHE` name whenever you ship changes, because the old cache is removed during `activate`. Browsers only offer the install prompt after the manifest, icons, and service worker are all in place.

```html
<form id="wizard" novalidate>
  <fieldset data-step>
    <legend>Account</legend>
    <input name="email" type="email" required placeholder="Email">
    <input name="password" type="password" required minlength="8" placeholder="Password (8+)">
  </fieldset>
  <fieldset data-step hidden>
    <legend>Profile</legend>
    <input name="name" required placeholder="Full name">
    <input name="age" type="number" min="13" max="120" required placeholder="Age">
  </fieldset>
  <fieldset data-step hidden>
    <legend>Review</legend>
    <p id="summary"></p>
  </fieldset>
  <button type="button" id="back">Back</button>
  <button type="button" id="next">Next</button>
  <button type="submit" id="submit" hidden>Create account</button>
  <p id="err" role="alert"></p>
</form>

<script>
const form = document.getElementById("wizard");
const steps = [...form.querySelectorAll("[data-step]")];
let current = 0;

// Use the browser's built-in messages but show them in one place
function validateStep(i) {
  for (const field of steps[i].querySelectorAll("input")) {
    if (!field.checkValidity()) {
      document.getElementById("err").textContent = `${field.placeholder}: ${field.validationMessage}`;
      field.focus();
      return false;
    }
  }
  document.getElementById("err").textContent = "";
  return true;
}

function show(i) {
  steps.forEach((s, k) => s.hidden = k !== i);
  document.getElementById("back").hidden = i === 0;
  document.getElementById("next").hidden = i === steps.length - 1;
  document.getElementById("submit").hidden = i !== steps.length - 1;
  if (i === steps.length - 1) {
    const d = Object.fromEntries(new FormData(form));
    document.getElementById("summary").textContent = `${d.name}, ${d.age}, ${d.email}`;
  }
}

document.getElementById("next").onclick = () => {
  if (validateStep(current)) show(++current);
};
document.getElementById("back").onclick = () => show(--current);

form.addEventListener("submit", e => {
  e.preventDefault();
  if (!validateStep(current)) return;
  console.log("submit", Object.fromEntries(new FormData(form)));
});

show(0);
</script>
```

Validation is driven by HTML attributes such as `required`, `minlength`, and `min`. `novalidate` turns off the browser's default popups so the wizard can show errors in one place. `FormData` reads every field, and the review step uses it to build the summary.

Subscribers register for a specific event class, so `publish` delivers only matching events and the compiler checks the types.

```java
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;

public final class EventBus {
    private final Map<Class<?>, List<Consumer<?>>> handlers = new ConcurrentHashMap<>();

    public <E> Runnable subscribe(Class<E> type, Consumer<? super E> handler) {
        var list = handlers.computeIfAbsent(type, k -> new CopyOnWriteArrayList<>());
        list.add(handler);
        return () -> list.remove(handler);           // returns an unsubscribe action
    }

    @SuppressWarnings("unchecked")
    public <E> void publish(E event) {
        // Walk the class hierarchy so subscribers to a supertype also receive subclasses.
        for (Class<?> c = event.getClass(); c != null; c = c.getSuperclass()) {
            for (Consumer<?> h : handlers.getOrDefault(c, List.of()))
                ((Consumer<E>) h).accept(event);
        }
    }

    // ---- demo ----
    record UserCreated(String name) {}
    record OrderPlaced(int id) {}

    public static void main(String[] args) {
        var bus = new EventBus();
        Runnable unsub = bus.subscribe(UserCreated.class, e -> System.out.println("welcome " + e.name()));
        bus.subscribe(OrderPlaced.class, e -> System.out.println("order " + e.id()));

        bus.publish(new UserCreated("Ana"));
        bus.publish(new OrderPlaced(7));
        unsub.run();
        bus.publish(new UserCreated("Omar"));       // no output: unsubscribed
    }
}
```

Note that `ConcurrentHashMap` is missing from the imports above. Add `import java.util.concurrent.ConcurrentHashMap;`. `CopyOnWriteArrayList` makes iteration safe while handlers subscribe or unsubscribe during a publish. It's a good fit when reads far outnumber writes.

Records give you immutability for free. The builder collects values, validates them once in one place, and produces the record.

```java
import java.util.Objects;

public record HttpRequest(String method, String url, int timeoutMs, String body) {

    // Compact constructor: runs on every construction path (builder or direct call)
    public HttpRequest {
        Objects.requireNonNull(method, "method");
        Objects.requireNonNull(url, "url");
        if (!url.startsWith("https://")) throw new IllegalArgumentException("https only: " + url);
        if (timeoutMs <= 0 || timeoutMs > 60_000) throw new IllegalArgumentException("timeout out of range");
        method = method.toUpperCase();
    }

    public static Builder builder(String url) { return new Builder(url); }

    public static final class Builder {
        private final String url;
        private String method = "GET";
        private int timeoutMs = 5_000;
        private String body;

        private Builder(String url) { this.url = url; }

        public Builder method(String m)    { this.method = m; return this; }
        public Builder timeout(int ms)     { this.timeoutMs = ms; return this; }
        public Builder body(String b)      { this.body = b; return this; }

        public HttpRequest build() { return new HttpRequest(method, url, timeoutMs, body); }
    }

    public static void main(String[] args) {
        var req = HttpRequest.builder("https://api.example.com/items")
                             .method("post")
                             .timeout(2_000)
                             .body("{\"a\":1}")
                             .build();
        System.out.println(req);
    }
}
```

The compact constructor is the single place where invariants are checked, so no path can create an invalid object. Because the record is immutable, you can share it across threads without locks.

Define constraints with annotations, then check any object with reflection. This is the same mechanism behind Bean Validation (`@NotNull`, `@Size`).

```java
import java.lang.annotation.*;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;

public class Validation {

    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.FIELD)
    public @interface NotBlank {
        String message() default "must not be blank";
    }

    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.FIELD)
    public @interface Range {
        int min();
        int max();
    }

    public static List<String> validate(Object obj) throws IllegalAccessException {
        var errors = new ArrayList<String>();
        for (Field f : obj.getClass().getDeclaredFields()) {
            f.setAccessible(true);
            Object value = f.get(obj);

            if (f.isAnnotationPresent(NotBlank.class)) {
                if (value == null || value.toString().isBlank())
                    errors.add(f.getName() + " " + f.getAnnotation(NotBlank.class).message());
            }
            if (f.isAnnotationPresent(Range.class) && value instanceof Integer i) {
                Range r = f.getAnnotation(Range.class);
                if (i < r.min() || i > r.max())
                    errors.add(f.getName() + " must be between " + r.min() + " and " + r.max());
            }
        }
        return errors;
    }

    static class Signup {
        @NotBlank String username = "  ";
        @Range(min = 13, max = 120) int age = 9;
    }

    public static void main(String[] args) throws Exception {
        validate(new Signup()).forEach(System.out::println);
        // username must not be blank
        // age must be between 13 and 120
    }
}
```

Use `getAnnotation` only on fields where `isAnnotationPresent` is true. Remember that `RUNTIME` retention is required, or the annotation is invisible to reflection. Production code should cache the reflected field list per class, because reflection is slow in hot paths.

```java
import java.time.Duration;
import java.util.List;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class Aggregator {
    static final ExecutorService POOL = Executors.newVirtualThreadPerTaskExecutor();

    static String fetchPrice(String vendor) {
        try { Thread.sleep(vendor.length() * 300L); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return vendor + ":42";
    }

    static CompletableFuture<String> priceFrom(String vendor) {
        return CompletableFuture
            .supplyAsync(() -> fetchPrice(vendor), POOL)
            .completeOnTimeout(vendor + ":unavailable", 800, TimeUnit.MILLISECONDS)  // slow vendor -> placeholder
            .exceptionally(ex -> vendor + ":error");                               // failure -> placeholder
    }

    public static void main(String[] args) {
        List<CompletableFuture<String>> futures = List.of("acme", "globex", "initech")
            .stream().map(Aggregator::priceFrom).toList();

        String result = CompletableFuture.allOf(futures.toArray(CompletableFuture[]::new))
            .thenApply(v -> futures.stream().map(CompletableFuture::join).collect(Collectors.joining(", ")))
            .orTimeout(3, TimeUnit.SECONDS)
            .join();

        System.out.println(result);
        POOL.shutdown();
    }
}
```

`completeOnTimeout` supplies a value after a delay and keeps the pipeline moving. `exceptionally` converts failures to fallbacks. Use `orTimeout` on the combined future to cap the total wait. Avoid calling `join()` inside another async task that is waiting on the same pool, because that can deadlock.

No frameworks or dependencies. `com.sun.net.httpserver` ships with the JDK.

```java
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpServer;

import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;

public class MiniServer {
    static final Map<String, String> store = new ConcurrentHashMap<>();

    public static void main(String[] args) throws IOException {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);

        server.createContext("/kv", exchange -> {
            try {
                String key = exchange.getRequestURI().getQuery();   // /kv?key=name
                switch (exchange.getRequestMethod()) {
                    case "GET" -> {
                        String v = store.get(key);
                        if (v == null) send(exchange, 404, "{\"error\":\"not found\"}");
                        else send(exchange, 200, "{\"value\":\"" + v + "\"}");
                    }
                    case "PUT" -> {
                        String body = new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
                        store.put(key, body.strip());
                        send(exchange, 204, "");
                    }
                    case "DELETE" -> {
                        store.remove(key);
                        send(exchange, 204, "");
                    }
                    default -> send(exchange, 405, "{\"error\":\"method not allowed\"}");
                }
            } finally {
                exchange.close();
            }
        });

        server.setExecutor(Executors.newVirtualThreadPerTaskExecutor());
        server.start();
        System.out.println("Listening on http://localhost:8080/kv");
    }

    static void send(HttpExchange ex, int status, String body) throws IOException {
        byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
        ex.getResponseHeaders().add("Content-Type", "application/json");
        ex.sendResponseHeaders(status, bytes.length == 0 ? -1 : bytes.length);
        if (bytes.length > 0) try (OutputStream os = ex.getResponseBody()) { os.write(bytes); }
    }
}
```

Test with: `curl -X PUT -d "hello" "localhost:8080/kv?key=greet"` and then `curl "localhost:8080/kv?key=greet"`. Note that `send` passes `-1` for no-body responses, which tells the server to send no content. Parsing query strings properly would need a real parser, and the JSON here is built by hand, so a library such as Jackson is safer when values may contain quotes.

```java
import java.sql.*;
import java.math.BigDecimal;

public class Accounts {
    private final String url;   // e.g. jdbc:postgresql://localhost/bank

    public Accounts(String url) { this.url = url; }

    /** Moves money atomically: both updates commit together or neither does. */
    public void transfer(long fromId, long toId, BigDecimal amount) throws SQLException {
        try (Connection conn = DriverManager.getConnection(url, "app", System.getenv("DB_PASS"))) {
            conn.setAutoCommit(false);
            try {
                debit(conn, fromId, amount);
                credit(conn, toId, amount);
                conn.commit();
            } catch (SQLException | RuntimeException e) {
                conn.rollback();
                throw e;
            }
        }
    }

    private void debit(Connection c, long id, BigDecimal amount) throws SQLException {
        try (PreparedStatement ps = c.prepareStatement(
                "UPDATE accounts SET balance = balance - ? WHERE id = ? AND balance >= ?")) {
            ps.setBigDecimal(1, amount);
            ps.setLong(2, id);
            ps.setBigDecimal(3, amount);
            if (ps.executeUpdate() != 1)
                throw new IllegalStateException("insufficient funds or unknown account " + id);
        }
    }

    private void credit(Connection c, long id, BigDecimal amount) throws SQLException {
        try (PreparedStatement ps = c.prepareStatement(
                "UPDATE accounts SET balance = balance + ? WHERE id = ?")) {
            ps.setBigDecimal(1, amount);
            ps.setLong(2, id);
            if (ps.executeUpdate() != 1)
                throw new IllegalStateException("unknown account " + id);
        }
    }
}
```

Three details matter here. `BigDecimal` avoids the rounding errors of `double` for money. The balance check sits inside the `WHERE` clause, so it can't race with other transactions. Any failure triggers `rollback`. In production, use a connection pool such as HikariCP instead of `DriverManager.getConnection` on every call.

Parses arithmetic like `2 + 3 * (4 - 1)` into an AST, then evaluates it. Respects operator precedence and parentheses.

```java
import java.util.List;

public class Calc {
    sealed interface Expr permits Num, Bin, Neg {}
    record Num(double value) implements Expr {}
    record Bin(char op, Expr left, Expr right) implements Expr {}
    record Neg(Expr inner) implements Expr {}

    static double eval(Expr e) {
        return switch (e) {
            case Num n -> n.value();
            case Neg n -> -eval(n.inner());
            case Bin b -> {
                double l = eval(b.left()), r = eval(b.right());
                yield switch (b.op()) {
                    case '+' -> l + r;
                    case '-' -> l - r;
                    case '*' -> l * r;
                    case '/' -> {
                        if (r == 0) throw new ArithmeticException("division by zero");
                        yield l / r;
                    }
                    default -> throw new IllegalStateException("op " + b.op());
                };
            }
        };
    }

    // ---- parser: expr -> term (('+'|'-') term)* ; term -> factor (('*'|'/') factor)* ; factor -> '-' factor | num | '(' expr ')'
    static class Parser {
        private final String src;
        private int pos = 0;
        Parser(String src) { this.src = src.replace(" ", ""); }

        Expr parse() {
            Expr e = expr();
            if (pos != src.length()) throw error("unexpected '" + src.charAt(pos) + "'");
            return e;
        }

        private Expr expr() {
            Expr left = term();
            while (peek('+') || peek('-')) {
                char op = src.charAt(pos++);
                left = new Bin(op, left, term());
            }
            return left;
        }

        private Expr term() {
            Expr left = factor();
            while (peek('*') || peek('/')) {
                char op = src.charAt(pos++);
                left = new Bin(op, left, factor());
            }
            return left;
        }

        private Expr factor() {
            if (peek('-')) { pos++; return new Neg(factor()); }
            if (peek('(')) {
                pos++;
                Expr e = expr();
                if (!peek(')')) throw error("expected ')'");
                pos++;
                return e;
            }
            int start = pos;
            while (pos < src.length() && (Character.isDigit(src.charAt(pos)) || src.charAt(pos) == '.')) pos++;
            if (start == pos) throw error("expected number");
            return new Num(Double.parseDouble(src.substring(start, pos)));
        }

        private boolean peek(char c) { return pos < src.length() && src.charAt(pos) == c; }
        private IllegalArgumentException error(String msg) {
            return new IllegalArgumentException(msg + " at position " + pos);
        }
    }

    public static void main(String[] args) {
        for (String s : List.of("2 + 3 * (4 - 1)", "-(2+3)*2", "10 / (5 - 5)", "2 +")) {
            try {
                System.out.println(s + " = " + eval(new Parser(s).parse()));
            } catch (RuntimeException ex) {
                System.out.println(s + " -> " + ex.getMessage());
            }
        }
    }
}
```

Each grammar rule becomes one method, so precedence comes from call depth: `term` calls `factor`, so `*` binds tighter than `+`. The sealed hierarchy lets the `switch` in `eval` be exhaustive with no default case for the node types.

`computeIfAbsent` runs the expensive function at most once per key, even when many threads ask for the same key at the same time.

```java
import java.util.Map;
import java.util.concurrent.*;
import java.util.function.Function;

public final class Memoizer {
    public static <K, V> Function<K, V> memoize(Function<K, V> fn) {
        Map<K, V> cache = new ConcurrentHashMap<>();
        return key -> cache.computeIfAbsent(key, fn);
    }

    // Caches futures so that concurrent callers wait on one computation
    public static <K, V> Function<K, V> memoizeAsync(Function<K, V> fn) {
        Map<K, CompletableFuture<V>> cache = new ConcurrentHashMap<>();
        return key -> cache.computeIfAbsent(key,
                k -> CompletableFuture.supplyAsync(() -> fn.apply(k))).join();
    }

    static long slowSquare(long n) {
        try { Thread.sleep(500); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return n * n;
    }

    public static void main(String[] args) throws InterruptedException {
        var fast = memoize(Memoizer::slowSquare);
        long t = System.nanoTime();
        System.out.println(fast.apply(12));   // ~500 ms
        System.out.println(fast.apply(12));   // instant
        System.out.printf("%d ms%n", (System.nanoTime() - t) / 1_000_000);
    }
}
```

Caution: the mapping function given to `computeIfAbsent` must be short and must not modify the same map, or it can deadlock or throw `IllegalStateException`. That is why the async variant stores the future, which is created quickly, and the slow work runs outside the map's lock. Also note that the cache has no size limit, so use it only for bounded key sets.

Streams a large file line by line, so memory use stays flat no matter the file size.

```java
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.Map;
import java.util.stream.Collectors;

public class WordCount {
    public static void main(String[] args) throws IOException {
        Path path = Path.of(args.length > 0 ? args[0] : "book.txt");

        try (var lines = Files.lines(path, StandardCharsets.UTF_8)) {   // closes the file
            Map<String, Long> counts = lines
                .flatMap(line -> java.util.Arrays.stream(line.toLowerCase().split("\\W+")))
                .filter(w -> !w.isBlank())
                .collect(Collectors.groupingBy(w -> w, Collectors.counting()));

            counts.entrySet().stream()
                .sorted(Map.Entry.<String, Long>comparingByValue().reversed()
                        .thenComparing(Map.Entry.comparingByKey()))
                .limit(10)
                .forEach(e -> System.out.printf("%-15s %d%n", e.getKey(), e.getValue()));
        }
    }
}
```

`Files.lines` must be closed, which is why it sits in try-with-resources. Note that `groupingBy` still keeps every distinct word in memory, so for a truly huge vocabulary use a count-min sketch or write partial counts to disk.

Shows the classic monitor pattern that underlies `java.util.concurrent.ArrayBlockingQueue`. It's worth understanding even if you use the library version.

```java
public class BoundedBuffer<T> {
    private final Object[] items;
    private int head, tail, count;

    public BoundedBuffer(int capacity) {
        items = new Object[capacity];
    }

    public synchronized void put(T item) throws InterruptedException {
        while (count == items.length)      // loop, not if: guards against spurious wakeups
            wait();
        items[tail] = item;
        tail = (tail + 1) % items.length;
        count++;
        notifyAll();
    }

    @SuppressWarnings("unchecked")
    public synchronized T take() throws InterruptedException {
        while (count == 0)
            wait();
        T item = (T) items[head];
        items[head] = null;                // let GC reclaim it
        head = (head + 1) % items.length;
        count--;
        notifyAll();
        return item;
    }

    public static void main(String[] args) {
        var buf = new BoundedBuffer<Integer>(3);

        Thread producer = new Thread(() -> {
            try { for (int i = 1; i <= 6; i++) { buf.put(i); System.out.println("put " + i); } }
            catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });
        Thread consumer = new Thread(() -> {
            try { for (int i = 0; i < 6; i++) System.out.println("took " + buf.take()); }
            catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });

        producer.start(); consumer.start();
    }
}
```

Use `while` around `wait()` every time, because a thread can wake up without a signal. `notifyAll` is safer than `notify` because it wakes both producers and consumers. In real systems, prefer `ArrayBlockingQueue` or `LinkedBlockingQueue`.

A `Collector` is built from four parts: a supplier, an accumulator, a combiner, and a finisher. Implementing one shows how `Collectors.toList` and friends actually work.

```java
import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Collectors2 {
    // Joins the values of each group into one comma-separated string
    public static <T, K> Collector<T, ?, Map<K, String>> joiningBy(
            Function<T, K> key, Function<T, String> value) {

        Supplier<Map<K, StringJoiner>> supplier = HashMap::new;

        BiConsumer<Map<K, StringJoiner>, T> accumulator = (m, t) ->
            m.computeIfAbsent(key.apply(t), k -> new StringJoiner(", ")).add(value.apply(t));

        BinaryOperator<Map<K, StringJoiner>> combiner = (a, b) -> {     // used only by parallel streams
            b.forEach((k, sj) -> a.merge(k, sj, (x, y) -> { x.merge(y); return x; }));
            return a;
        };

        Function<Map<K, StringJoiner>, Map<K, String>> finisher = m -> {
            Map<K, String> out = new TreeMap<>();
            m.forEach((k, sj) -> out.put(k, sj.toString()));
            return out;
        };

        return Collector.of(supplier, accumulator, combiner, finisher);
    }

    public static void main(String[] args) {
        record Pet(String owner, String name) {}
        var pets = List.of(new Pet("Ana", "Rex"), new Pet("Omar", "Tom"), new Pet("Ana", "Mia"));

        Map<String, String> result = pets.stream()
            .collect(joiningBy(Pet::owner, Pet::name));
        System.out.println(result);   // {Ana=Rex, Mia, Omar=Tom}
    }
}
```

The combiner runs only for parallel streams, and it's easy to get wrong. Test with `.parallel()` when you write one. Note that `StringJoiner.merge` appends another joiner's contents, which is why the combiner calls it.

